LOG = {e["saved_file"]: e for e in json.load(open(HERE / "sources/fetch_log.json")) if "saved_file" in e}
SEF = "https://www.sefaria.org/api/v3/texts/"


def src(sid, file, edition, note=None):
    path = HERE / file
    entry = LOG.get(file, {})
    item = {"source_id": sid, "url": entry.get("url"), "edition": edition,
            "fetched_at": entry.get("fetched_at"), "saved_file": file,
            "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
    if entry.get("post_body"):
        item["post_body"] = entry["post_body"]
    if note:
        item["note"] = note
    return item


